from typing import Any

# A hand-rolled validation layer: ad-hoc checks scattered in
# every handler, easy to forget, and no OpenAPI schema output.
class LegacyOrderService:
    def create_order(self, payload: dict[str, Any]) -> dict[str, Any]:
        user_id = payload.get("user_id")
        if user_id is None or not isinstance(user_id, int):
            return {"error": "user_id must be an int", "status": 400}
        items = payload.get("items")
        if not isinstance(items, list) or not items:
            return {"error": "items must be a non-empty list", "status": 400}
        total = 0.0
        for item in items:
            price = item.get("price")  # ❌ OLD: ad-hoc dict check, no coercion ('9.99' stays str → "bad price")
            if not isinstance(price, (int, float)):
                return {"error": f"bad price in {item}", "status": 400}
            total += price * int(item.get("qty", 1))
        return {"order_id": 1, "total": total, "status": 201}


service = LegacyOrderService()
result = service.create_order({"user_id": 7, "items": [{"price": "9.99", "qty": 2}]})
print(result)  # error: "bad price" because price arrived as a string
